SELECT ROUND(100.0 * chlorine_atoms * 1.0 / total_atoms, 4) AS chlorine_percentage
FROM (
    SELECT 
        (SELECT COUNT(*) FROM atom WHERE molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '-')) AS total_atoms,
        (SELECT COUNT(*) FROM atom WHERE molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '-') AND element = 'cl') AS chlorine_atoms
);
